INSERT INTO scholarship (name, provider, description, amount, application_url, min_age, max_age, required_gender, eligible_region, required_military_status, max_income_bracket, min_gpa, min_gpa_basis, requires_disability, foreigner_eligibility, grade_level, major, affiliated_institution, min_credits, admission_score_condition, headcount, application_period, eligible_university, eligible_college, required_enrollment_status, min_grade, max_grade, required_degree_level, category_l1, category_l2) VALUES
('레인보우장학금', '한남대학교', '학생경력마일리지 점수를 7단계(빨/주/노/초/파/남/보)로 나눠 차등 지급(연 15만~85만원, 학년별 점수 기준 다름). 어학성적 최저기준 충족 필요. 마일리지·어학점수 혼합조건이라 구조화된 필드로 매칭 불가.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
('진리장학금', '한남대학교', '수시 학생부교과전형 환산총점 상위 3명 대상. 등록금 전액+학기당 도서비 200만원. 평점평균 3.70 이상 유지 시 4년간 지속.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'academic_merit'),
('자유장학금', '한남대학교', '수시 학생부교과전형 환산총점 상위 6명 대상(진리장학금 다음 순위). 등록금 전액+도서비 지원.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'academic_merit'),
('인돈장학금', '한남대학교', '단과대학·독립학부별 수석합격자 대상. 등록금 전액+학기당 도서비 100만원. 평점평균 3.70 이상 유지 시 2년간 지속.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'academic_merit'),
('청림장학금', '한남대학교', '모집단위(학과)별 우수합격자 대상. 수석은 등록금 전액, 차석은 등록금 50% 지급.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'academic_merit'),
('성적우수장학금(한남대)', '한남대학교', '정규학기 재학생, 직전학기 평점평균 2.0 이상·15학점 이상 취득자 대상(졸업학기는 12학점 이상). 학부(과)·전공·학년별 재학생의 12% 이내 선발.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, 2.0, 'semester', NULL, NULL, NULL, NULL, NULL, '15학점 이상(졸업학기 12학점 이상)', NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'academic_merit'),
('한남드림장학금', '한남대학교', '기초생활수급자·차상위계층 및 기타 경제사정 곤란자 대상. 예산범위 내 등록금 선감면 지급.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'welfare_living'),
('희망드림장학금', '한남대학교', '평소 품행이 단정하고 모범이 되는 재학생 중 경제적 사정으로 학업보조가 필요한 학생 대상. 직전학기 평점평균 2.0 이상·15학점 이상 취득자. 100만원(등록금 범위 내) 지급.', 1000000, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, 2.0, 'semester', NULL, NULL, NULL, NULL, NULL, '15학점 이상', NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'welfare_living'),
('보람장학금', '한남대학교', '학교가 인정하는 기관·시설에서 학기당 130시간 이상 봉사활동을 한 학생 대상. 학기당 50만원 지급.', 500000, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
('면학장학금(한남대)', '한남대학교', '본인 또는 부모가 장애인(3급 이내)이며 성적이 우수한 학생 대상(입학 후 2번째 학기부터). 평점평균 3.70 이상(장애학생 본인은 3.0 이상)은 등록금 40%, 평점평균 3.50~3.70 미만(장애학생 본인은 2.0~3.0 미만)은 등록금 30% 지원. "본인 또는 부모의 장애"라는 OR 조건이라 requires_disability 하나로 표현 불가.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('튜터장학금', '한남대학교', '3·4학년 중 전체 성적 우수자 또는 운영교과목 기수강 성적우수자(평점평균 3.8 이상)가 튜터로 선발된 경우 지급. 70만원(우수튜터 선정 시 20만원 추가).', 700000, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, 3.8, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
('어학인재장학금(한남대)', '한남대학교', '어학 성적 우수 신입생 대상. 시험 종류·점수 조건이라 현재 시스템 필드로는 매칭 불가. 2026-08-02 재검증: 2018학년도 정시모집요강 공식 자료에서 이 정확한 명칭을 찾지 못함 — 명칭이 바뀌었거나 폐지됐을 가능성 있음(유사 취지의 "외국어특별장학금"은 현재도 존재). 여전히 저신뢰 상태, 추후 재확인 권장.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'academic_merit'),
('글로벌인재장학금(한남대)', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): 특별전형(글로벌인재전형) 수석합격자 1명 대상, 입학 첫 학기 등록금 선감면으로 수업료 70% 지급(입학금 제외).', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'academic_merit'),
('성적향상장학금', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): 직전 학기 대비 성적이 2등급 이상 향상된 재학생 중 일정 인원 선발(절대 성적이 아닌 향상폭 기준이라 min_gpa로 표현 불가). 학기당 50만원.', 500000, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'academic_merit'),
('고른기회장학금', '한남대학교', '사회통합전형 등 고른기회 특별전형 입학생 대상. 2026-08-02 재검증: 2018학년도 정시모집요강 공식 자료에서 이 정확한 명칭을 찾지 못함 — 명칭이 바뀌었거나 폐지됐을 가능성 있음. 여전히 저신뢰 상태, 추후 재확인 권장.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'special_target'),
('농어촌학생장학금(한남대)', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): 농어촌특별전형 수석합격자 1명 대상(거주지가 아닌 출신 학교 소재지 기준이라 eligible_region으로 표현 불가). 입학 첫 학기 등록금 선감면으로 수업료 70% 지급(입학금 제외).', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'special_target'),
('기초생활수급자·차상위계층장학금(한남대, 신입생)', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): 기초생활수급자·차상위계층 특별전형 수석합격자 1명 대상. 입학 첫 학기 등록금 선감면으로 수업료 70% 지급(입학금 제외). 재학생 대상의 유사 취지 장학금은 별도로 "한남드림장학금"(소득분위별 차등 지급) 존재.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'welfare_living'),
('검정고시출신자장학금', '한남대학교', '검정고시 출신 신입생 대상. 2026-08-02 재검증: 2018학년도 정시모집요강 공식 자료에는 독립된 "검정고시출신자장학금" 항목은 없고, "다니엘장학금"의 신청자격 산식에서 "검정고시출신자 별도산식 적용"이라는 언급만 확인됨 — 별도 장학금이 아니라 다니엘장학금 산정 방식의 한 조항일 가능성이 있음. 여전히 저신뢰 상태, 추후 재확인 권장.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'special_target'),
('외국인장학금(한남대)', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): 외국인 특례 신·편입학자 대상. 입학 시 수업료 50%+입학금 전액, 이후 재학기간 중 평점평균 4.00 이상이면 수업료 100%, 3.50~4.00 미만 50%, 2.50~3.50 미만 30% 지급.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'foreigner_only', NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'special_target'),
('해외선교사자녀장학금', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): 재외국민 특별전형 합격자 중 선교 파송훈련을 받고 외국에서 2년 이상 선교활동을 했거나 마치고 귀국한 선교사의 자녀로, 외국 학교에서 고교과정 1년 포함 중·고교 연속 2년(4학기) 이상 재학 후 귀국한 자(선교 파송기관은 한국기독교교회협의회(KNCC) 인정 단체이거나 준하는 단체여야 함, 한남대는 기독교 재단 학교). 입학 시 수업료 50%+입학금 전액, 이후 평점평균 4.00 이상 100%/3.50~4.00 미만 50%/2.50~3.50 미만 30% 지급.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('체육특기자장학금(한남대)', '한남대학교', '2026-08-02 재검증(2005년 개정 장학금지급규정 원문으로 확인, 이후 세부 금액은 변동 가능성 있음): 체육특기자 전형 입학생 대상, 재학기간 중 특별한 사유 없으면 등록금 전액+생활보조금 지급. 단, 입학 기준 2년 단위로 전국 규모 대회 3위 이내 입상 성적이 없으면 등록금 70%만 지급.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'activity_merit'),
('편입생장학금(한남대)', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): 일반/학사 편입학생 대상, 입학금 전액 면제.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, 'undergrad_transfer', NULL, NULL, NULL, 'school_internal', 'academic_merit'),
('환경미화원자녀장학금', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): 시·군·구 소속 환경미화원의 자녀인 신입생 대상(신청자에 한함). 입학 첫 학기 수업료 70% 지급(입학금 제외).', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'special_target'),
('동문자녀장학금(한남대)', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): 한남대학교 학부 졸업생(동문)의 자녀인 신입생 대상(신청자에 한해 지급). 입학 첫 학기 입학금 지급.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'special_target'),
('장애인전형장학금', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인, 정식 명칭 "장애인 등 대상자전형장학금"): 장애인 등 대상자 전형으로 선발된 신입생 대상, 입학금 전액 면제.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'special_target'),
('영어우수장학금(한남대)', '한남대학교', '영어 능력시험 성적 우수 학생 대상. 시험 종류·점수 조건이라 현재 시스템 필드로는 매칭 불가. 2026-08-02 재검증: 2018학년도 정시모집요강 공식 자료에서는 이 정확한 명칭을 찾지 못함(2005년 규정에는 "외국어영역 성적 우수자 장학금"으로 존재) — 명칭이 바뀌었거나 폐지됐을 가능성 있음. 유사 취지로 "외국어특별장학금"(외국어교육원 특별프로그램 이수자 대상)은 현재도 존재 확인. 여전히 저신뢰 상태, 추후 재확인 권장.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'academic_merit'),
('재외국민장학금', '한남대학교', '재외국민 전형 입학생 대상. 2026-08-02 재검증: 2018학년도 정시모집요강에는 "재외국민장학금"이라는 독립된 항목명은 없고, "외국인장학금"(외국인 특례 신·편입학자, 평점평균별 수업료 30~100%)과 "해외선교사자녀장학금"(재외국민 특별전형 합격자 중 선교사 자녀 한정) 항목에서 재외국민전형 합격자를 다루고 있음 — 순수 재외국민(비선교사 자녀) 대상 장학금이 외국인장학금에 통합됐을 가능성 있음. 여전히 저신뢰 상태, 추후 재확인 권장.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'special_target'),
('고시장학금', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): 국가직·지방직 5급시험(외교관후보자시험 포함), 입법고시, 법원행정고시, 공인회계사시험, 변리사시험 1차에 합격한 재학생 대상. 평점평균 3.70 이상 유지 시 재학 중 수업료 전액 지급. (신입생 대상 별도 버전도 있으며 도서비 학기당 120만원 추가 지급, 수능 성적 기준 선발 가능)', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, 3.7, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'academic_merit'),
('미술우수자장학금(한남대)', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인, 기존 "미술/문학우수자장학금" 1건을 미술·문학 2건으로 분리): 고교 재학 중 한남대 주최 전국고교 미술실기대회에서 입학시점 3년 이내 입상하고 융합디자인전공·회화전공·미술교육과에 입학한 자(성적우수 중복수혜 불가). 대상(최우수상, 3명 이내)은 수업료+입학금 전액을 4년간, 우수상(6명 이내)은 수업료 70%(입학금 제외)를 2년간 지급하며 평점평균 3.50 이상 유지 필요.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, 3.5, NULL, NULL, NULL, 1, '융합디자인전공,회화전공,미술교육과', NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'activity_merit'),
('문학우수자장학금(한남대)', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인, 기존 "미술/문학우수자장학금" 1건을 미술·문학 2건으로 분리): 고교 재학 중 한남대 주최 전국고교 백일장에서 입학시점 3년 이내 입상하고 국어국문·창작학과, 영어영문학과, 외국어문학부, 국어교육과, 영어교육과에 입학한 자(성적우수 중복수혜 불가). 대상(1명 이내)은 수업료+입학금 전액을 4년간, 금상(2명 이내)은 수업료 70%(입학금 제외)를 2년간 지급하며 평점평균 3.50 이상 유지 필요.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, 3.5, NULL, NULL, NULL, 1, '국어국문·창작학과,영어영문학과,외국어문학부,국어교육과,영어교육과', NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'activity_merit'),
('모의UN경시장학금', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): 고교 재학 중 한남대 주최 전국 모의UN경시대회에서 입학시점 3년 이내 입상하고 한남대에 입학한 자(전공 무관, 성적우수 중복수혜 불가). 대상(4명 이내)은 수업료+입학금 전액을 4년간, 최우수상(4명 이내)은 수업료 70%(입학금 제외)를 2년간 지급하며 평점평균 3.50 이상 유지 필요.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, 3.5, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'activity_merit'),
('보훈장학금(한남대)', '한남대학교', '2026-08-02 재검증(2018학년도 정시모집요강 공식 자료로 확인): ①국가유공자 자녀 — 8학기까지만 지급, 직전 학기 실점평균(100점 만점) 70점 이상인 경우에 한함. ②국가유공자 본인 및 배우자 — 성적·학기 무관하게 졸업 시까지 지원(보훈처 교육지원 업무기준에 의거). 수업료 전액 지급.', NULL, 'http://janghak.hannam.ac.kr/main/', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 초 공지 (한남대 홈페이지 확인)', '한남대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
